window.RP_SESSION={"id":"S-f777dc4d07fd","messages":[{"id":"RP-III-0062262","time":"2026-04-01T15:50:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"길드 강가에서 낚싯대를 드리우고 있는 우슬라.\n\n천천히 미끼를 흔들며 물고기를 유인하는 그의 모습은 숙련된 낚시꾼처럼 보인다.\n\n\"오늘은 뭐가 올라올까나?\"","characters":["P-d077092ffb19"]},{"id":"RP-III-0062263","time":"2026-04-01T15:54:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"'부스럭-'\n\n 수풀들을 치우며 낚시터에 나타난 조바. 아무도 없을 줄 알았던 낚시터에 이미 사람 한 명이 있는 걸 발견하고 살짝 놀란 표정을 짓습니다.\n\n\" 아.. 안녕하세요? \"","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062264","time":"2026-04-01T15:55:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"반갑네!\"\n\n환히 웃으며 그를 맞이합니다.","characters":["P-d077092ffb19"]},{"id":"RP-III-0062265","time":"2026-04-01T15:55:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 예, 음... 혹시, 길드 사람이신가요? \"","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062266","time":"2026-04-01T16:00:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"당연하지. 새로 들어온 우슬라라고 하네!\"","characters":["P-d077092ffb19"]},{"id":"RP-III-0062267","time":"2026-04-01T16:03:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 아, 우슬라 씨.. 반갑습니다. 하일로 조바라고 합니다. \"\n\n 그에게 가볍게 목례를 하며 악수를 청합니다","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062268","time":"2026-04-01T16:21:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"그의 악수를 흔쾌히 받는다.\n\n\"앞으로 잘 지내 보세나!\"\n\n그 때, 그의 낚싯대가 팽팽해집니다.","characters":["P-d077092ffb19"]},{"id":"RP-III-0062269","time":"2026-04-01T16:22:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"어이쿠, 낚였구먼.\"\n\n그는 빠르게 자세를 잡고 릴을 감아올립니다. 헌데 이상하군요. 낚싯대가 꿈쩍도 하지 않습니다.","characters":["P-d077092ffb19"]},{"id":"RP-III-0062270","time":"2026-04-01T16:27:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 완전 대어인가 본데요? \"\n\n 그의 힘만으론 꿈쩍도 하지 않는 낚싯대를 보고 그를 도와주기 위해 옆에서 낚싯대를 잡아 힘을 보태줍니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062271","time":"2026-04-01T16:31:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-d077092ffb19"]},{"id":"RP-III-0062272","time":"2026-04-01T16:31:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 7 = 7\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0062273","time":"2026-04-01T16:32:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"조바의 도움에도 불구하고, 낚싯대와 그것을 붙들고 버티는 두 명은 점점 강쪽으로 끌려갑니다!","characters":["P-d077092ffb19"]},{"id":"RP-III-0062274","time":"2026-04-01T16:35:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 어어?! \"","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062275","time":"2026-04-01T16:40:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"보통내기가 아니구먼! 마물인가?\"","characters":["P-d077092ffb19"]},{"id":"RP-III-0062276","time":"2026-04-01T16:43:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 끄으..! 그럴지도요..? 아! 잠시만요! \"\n\n 급하게 바이올린을 켜서 그의 힘을 증폭시킬 음악을 연주해 봅니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062277","time":"2026-04-01T16:43:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062278","time":"2026-04-01T16:43:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'하일로 조바'의 지능 판정 :\n[10] + [0] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0062279","time":"2026-04-01T16:44:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 크레셴도- \"\n\n점점 커지는 연주로 그의 힘을 업! 시켜줍니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062280","time":"2026-04-01T16:47:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"오옷... 힘이... 넘치는구만!!\"\n\n그가 더 이상 끌려가지 않고 버티기 시작하자, 낚싯대가 부러질 기세로 휘어집니다.","characters":["P-d077092ffb19"]},{"id":"RP-III-0062281","time":"2026-04-01T16:47:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-d077092ffb19"]},{"id":"RP-III-0062282","time":"2026-04-01T16:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 10 = 10\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0062283","time":"2026-04-01T16:48:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"영 차!!\"\n\n그의 기합과 함께, 수면 위로 거대한 메기가 솟아오릅니다!","characters":["P-d077092ffb19"]},{"id":"RP-III-0062284","time":"2026-04-01T16:52:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 오오-! 이렇게 큰 메기는 처음 봐요! \"\n\n 거의 사람 만 한 그 메기를 신기하게 봅니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062285","time":"2026-04-01T16:57:00+09:00","room":"RP III","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"하하! 이런 놈이어야 잡는 맛이 있지!\"\n\n물밖으로 끌려나온 메기의 아가미에 손을 넣고 다른 손으로는 몸통을 받친 뒤, 영차 하고 들어올린다.\n\n\"길드 전우들에게 전하게, 당분간 메기를 질리도록 먹게 될 거라고 말야!\"","characters":["P-d077092ffb19"]},{"id":"RP-III-0062286","time":"2026-04-01T17:03:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 하핫, 그러죠! \"\n\n 메기 잡은 게 좋은지, 어린아이처럼 싱글벙글하네요.","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062287","time":"2026-04-01T18:15:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0062288","time":"2026-04-01T18:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
